  pageIndex: state.pageIndex,
  pageCount: pageCount(lengthOf(rows), pageSize),
  canNext: canNext(state),
  canPrevious: canPrevious(state)
};

const m: AtomMachine<CsvState, CsvEvent<T>, void> = {
  id: 'csv-export',
  init() {
    return {
      status: 'empty',
      csv: '',
      rows: 0
    };
  },
  send(state, event) {
    return when(differs(event.type, 'EXPORT'), () => state, () => when(equals(lengthOf(event.rows), 0), () => when(equals(state.status, 'empty'), () => state, () => m.init()), () => ({
      status: 'ready',
      csv: toCsv(event.rows, columns, options),
      rows: lengthOf(event.rows)
    })));
  },
  stateOf(state) {
    return state.status;
  }
};
return m;

return when(differs(event.type, 'EXPORT'), () => state, () => when(equals(lengthOf(event.rows), 0), () => when(equals(state.status, 'empty'), () => state, () => m.init()), () => ({
  status: 'ready',
  csv: toCsv(event.rows, columns, options),
  rows: lengthOf(event.rows)
})));

return when(differs(event.type, 'EXPORT'), () => state, () => {
  const keys = keysOf(orElse(firstOf(event.rows), () => ({})));
  return createCsvMachine<Record<string, unknown>>(mapEach(keys, k => ({
    header: k,
    accessor: k
  }))).send(state, event);
});

let s = start;
let e = end;
when(and(differs(s, null), () => isValidDate(s)), () => s = startOfDay(s));
when(and(differs(e, null), () => isValidDate(e)), () => e = endOfDay(e));
return {
  status: statusOf(s, e),
  start: s,
  end: e
};

return when(differs(r.status, 'complete'), () => false, () => {
  const t = timeOfDate(d);
  return and(atLeast(t, timeOfDate(r.start as Date)), () => atMost(t, timeOfDate(r.end as Date)));
});

return {
  status: 'idle',
  text: '',
  query: '',
  dueAt: null,
  delay: orElse(get(input, "delay"), () => 300),
  minLength: orElse(get(input, "minLength"), () => 0)
};

const emptyA = isEmptyValue(a);
const emptyB = isEmptyValue(b);
return when(and(emptyA, () => emptyB), () => 0, () => when(emptyA, () => 1, () => when(emptyB, () => -1, () => when(and(isA(a, Date), () => isA(b, Date)), () => minus(timeOfDate(a), timeOfDate(b)), () => when(and(isNumber(a), () => isNumber(b)), () => minus(a, b), () => localeCompareText(textFrom(a), textFrom(b), undefined, {
  sensitivity: 'base',
  numeric: true
}))))));

return view({
  ...orElse(get(input, "filters"), () => ({}))
}, orElse(get(input, "search"), () => ''), orElse(get(input, "sort"), () => null));

return applyView(rows, machine.init({
  filters: options.filters,
  search: options.search,
  sort: options.sort
}), orElse(options.searchFields, () => []));

return match(event.type, {
  FETCH_FIRST: () => when(differs(state.loading, undefined), () => state, () => ({
    status: 'pending',
    pages: [],
    loading: null,
    error: null
  })),
  FETCH_NEXT: () => when(or(differs(state.loading, undefined), () => not(hasNextPage(state))), () => state, () => ({
    ...state,
    loading: nextCursor(state),
    error: null
  })),
  RESOLVE: () => when(or(equals(state.loading, undefined), () => differs(event.cursor, state.loading)), () => state, () => ({
    status: 'success',
    pages: added(state.pages, {
      items: event.items,
      cursor: event.cursor,
      nextCursor: event.nextCursor
    }),
    loading: undefined,
    error: null
  })),
  REJECT: () => when(or(equals(state.loading, undefined), () => differs(event.cursor, state.loading)), () => state, () => ({
    ...state,
    status: 'error',
    loading: undefined,
    error: event.error
  })),
  RESET: () => machine.init()
}, () => state);

return reduceTo(events, (s, e) => machine.send(s, e), machine.init({
  steps,
  data
})) as FlowState<D>;

return match(event.type, {
  APPLY: () => when(equals(state.status, 'applied'), () => ({
    ...state,
    value: event.update(state.value)
  }), () => ({
    status: 'applied',
    value: event.update(state.value),
    snapshot: state.value,
    error: null
  })),
  COMMIT: () => when(differs(state.status, 'applied'), () => state, () => when(equals(event.value, undefined), () => ({
    status: 'committed',
    value: state.value,
    snapshot: null,
    error: null
  }), () => ({
    status: 'committed',
    value: event.value,
    snapshot: null,
    error: null
  }))),
  ROLLBACK: () => when(differs(state.status, 'applied'), () => state, () => ({
    status: 'rolledBack',
    value: state.snapshot,
    snapshot: null,
    error: event.error
  }))
}, () => state);

const applied = machine.send(state, {
  type: 'APPLY',
  update
}) as OptimisticState<V>;
return await attemptAsync(async () => {
  const saved = await write(applied.value);
  return when(equals(saved, undefined), () => machine.send(applied, {
    type: 'COMMIT'
  }) as OptimisticState<V>, () => machine.send(applied, {
    type: 'COMMIT',
    value: saved
  }) as OptimisticState<V>);
}, async error => machine.send(applied, {
  type: 'ROLLBACK',
  error
}) as OptimisticState<V>);

return {
  pageIndex: state.pageIndex,
  pageSize: state.pageSize,
  offset: times(state.pageIndex, state.pageSize)
};

return when(equals(pageIndex, state.pageIndex), () => state, () => {
  const keeps = equals(state.status, 'success');
  return {
    ...state,
    pageIndex,
    fetching: true,
    placeholder: keeps,
    error: null
  };
});

return {
